@unittest.skipUnless(getattr(os, 'geteuid', lambda: -1)() == 0,
                     'real ISO tools are installed by the protected Root CI step')
class UbuntuCandidateDiscLayout(unittest.TestCase):
    def test_actual_iso_preserves_package_and_companion_under_candidate(self):
        from unittest import mock
        import shlex
        self.assertIsNotNone(shutil.which('genisoimage'))
        self.assertIsNotNone(shutil.which('isoinfo'))
        spec = importlib.util.spec_from_file_location(
            'candidate_disc_layout', SOURCE / 'prepare_observer_iso.py')
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        name = 'OPEMOS EXE Linux Test_0.1.0_amd64.AppImage'
        payload = b'unit package bytes; never executed'
        companion = b'{"unit":"appliance manifest"}'
        for relative in (name, 'future producer/linux/' + name):
            with self.subTest(relative=relative), tempfile.TemporaryDirectory() as temp:
                root = Path(temp)
                nonce, commit = 'a' * 32, 'c' * 40
                digest = hashlib.sha256(payload).hexdigest()
                descriptor = {'source_commit': commit, 'package_sha256': digest,
                              'executable_sha256': 'd' * 64}
                config = {'nonce': nonce, 'source_commit': commit,
                          'candidate': {'descriptor': descriptor, 'archive': {}},
                          'prepared_directory': str(root / 'prepared'),
                          'observer_source': {}, 'expanded_limit': 4096,
                          'guest_operation': {'nonce': nonce, 'source_commit': commit,
                              'package_sha256': digest, 'usb_serial': 'opemos-' + nonce,
                              'native_executable_sha256': 'd' * 64, 'display': [1600, 900]}}

                def extracted(_archive, _descriptor, destination, _limit):
                    # Archive authentication is exercised separately. This
                    # regression uses the real production ISO command/reader.
                    package = destination / relative
                    package.parent.mkdir(mode=0o700, parents=True)
                    package.write_bytes(payload)
                    manifest = Path(str(package) + '.runtime') / 'appliance/appliance-manifest.json'
                    manifest.parent.mkdir(mode=0o700, parents=True)
                    manifest.write_bytes(companion)
                    return {'package': {'name': relative}}

                with mock.patch.object(module, 'extract_candidate', side_effect=extracted), \
                        mock.patch.object(module, 'held_input', return_value=b'# unit observer'):
                    result = module.pipeline_medium(config)
                iso = result['path']
                paths = subprocess.run(['isoinfo', '-R', '-f', '-i', iso],
                                       capture_output=True, text=True, check=True).stdout.splitlines()
                expected = '/candidate/' + relative
                self.assertIn('/start.sh', paths)
                self.assertIn(expected, paths)
                for path, expected_bytes in [(expected, payload),
                        (expected + '.runtime/appliance/appliance-manifest.json', companion)]:
                    actual = subprocess.run(['isoinfo', '-R', '-i', iso, '-x', path],
                                            capture_output=True, check=True).stdout
                    self.assertEqual(actual, expected_bytes)
                script = (root / 'prepared/start.sh').read_text()
                self.assertIn(shlex.quote('/media/opemosgui/OPROBOT' + expected), script)
                self.assertLess(script.index('phase=guest_display'),
                                script.index('phase=native_app_and_observer'))
                subprocess.run(['bash', '-n', str(root / 'prepared/start.sh')], check=True)
                operation = json.loads(subprocess.run(
                    ['isoinfo', '-R', '-i', iso, '-x', '/operation.json'],
                    capture_output=True, check=True).stdout)
                self.assertEqual(operation['display'], [1600, 900])
                self.assertFalse(result['VMOrGUIAcceptance'])

@unittest.skipUnless(getattr(os, 'geteuid', lambda: -1)() == 0,
                     'actual protected Root filesystem/ISO regression')
class UbuntuSourceProducerInputs(unittest.TestCase):
    def load(self, name):
        spec=importlib.util.spec_from_file_location('source_producer_'+name,SOURCE/(name+'.py'))
        module=importlib.util.module_from_spec(spec);spec.loader.exec_module(module)
        return module

    def test_normal_create_materializer_reaches_actual_preflight_with_optional_workflow(self):
        from unittest import mock
        cycle=self.load('normal_cycle')
        with tempfile.TemporaryDirectory(prefix='opemos-create-preflight-',dir='/var/lib')as temp:
            root=Path(temp);root.chmod(0o755)
            runner=root/'runner';runner.mkdir();os.chown(runner,1000,1000);runner.chmod(0o700)
            private=root/'private';private.mkdir();os.chown(private,1000,1000);private.chmod(0o700)
            queue=root/'queue';queue.mkdir();config=root/'config';config.mkdir()
            def file(path,raw,uid=0,mode=0o444):
                path.parent.mkdir(parents=True,exist_ok=True)
                path.write_bytes(raw);os.chown(path,uid,uid);path.chmod(mode)
                return {'path':str(path),'sha256':hashlib.sha256(raw).hexdigest()}
            file(runner/'.runner',b'{"agentId":21,"agentName":"opemos-omen-robot"}',1000,0o600)
            for name in ('.credentials','.credentials_rsaparams','.env'):
                file(runner/name,b'fixture data only',1000,0o600)
            manifest=file(root/'runner-manifest.json',b'{}')
            login=file(private/'login',b'{"fixture":true}',1000,0o600)
            queue_pin=file(queue/'test_queue.py',b'fixture queue DATA',1000)
            logger=file(queue/'queue_job.py',b'fixture logger DATA',1000)
            # Only installation-location configuration is modeled. Both
            # maintained materialize() and preflight() bodies run unchanged,
            # against real Root/UID1000 files and their actual full identities.
            source=(SOURCE/'install_remote.py').read_bytes()+('\nROOT=Path('+repr(str(root))+')\n'+
                'RUNNER=Path('+repr(str(runner))+')\nCONFIG=Path('+repr(str(config))+')\n'+
                'QUEUE=Path('+repr(str(queue))+')\nPRIVATE=Path('+repr(str(private))+')\n').encode()
            temporary=types.ModuleType('fixture_installer_targets')
            exec(compile(source,'configured_actual_installer.py','exec'),temporary.__dict__)
            for path in temporary.targets({'policy':{'sourceBuildEnabled':True}}).values():
                if not path.exists():file(path,b'original installed target data')
            sha=lambda raw:hashlib.sha256(raw).hexdigest()
            control=b'opaque Root control fixture';hook=b'opaque Root hook fixture'
            closed={'currentManager':{'MainPID':'0','ControlGroup':''},'fullUID0Group':{'absent':True},
                    'oldDispatcherAbsent':True,'oldListenerAbsent':True}
            manager_result=subprocess.CompletedProcess(['modeled systemd'],0,
                b'LoadState=not-found\nActiveState=inactive\nMainPID=0\nControlGroup=\n',b'')
            for enabled in (False,True):
                template={'kind':'ROOT_REVIEWED_ROBOT_CONTROL_MATERIALIZATION_V1','mainCommit':'a'*40,
                    'runnerId':21,'queueSourceSHA256':queue_pin['sha256'],'queueLoggerSHA256':logger['sha256'],
                    'runnerManifest':manifest,'login':login,
                    'sources':{'control.py':{'hex':control.hex(),'sha256':sha(control)},
                               'job-started.sh':{'hex':hook.hex(),'sha256':sha(hook)}},
                    'policy':{'kind':'ROOT_NORMAL_UBUNTU_GUI_BUILD_WRITE_POLICY_V1','sourceCommit':'a'*40,
                        'queueSourceSHA256':queue_pin['sha256'],'queueLoggerSHA256':logger['sha256'],
                        'sourceBuildEnabled':enabled},
                    'registry':{'artifacts':{'ubuntu':{}}},'profile':{'fixed_registry':{}}}
                raw=cycle.enc(template)
                policy={'normalTemplateSHA256':sha(raw),'currentReleaseTx':'d'*32,
                    'normalInstallerSHA256':sha(source),'mainCommit':'a'*40,
                    'queueSourceSHA256':queue_pin['sha256'],'queueLoggerSHA256':logger['sha256'],
                    'controlBrokerSHA256':sha(control),'jobStartedSHA256':sha(hook)}
                probe=types.SimpleNamespace(pin_source=lambda *args:(source,{}))
                with mock.patch.object(cycle,'REMOTE_TEMPLATE_HEX',raw.hex(),create=True), \
                     mock.patch.object(cycle,'CONTROL',root), \
                     mock.patch.object(cycle,'closed_receipt',return_value=closed):
                    payload,installer=cycle.materialize(policy,probe,'e'*32,
                        {'unit':'opemos-testq-aa-bb.service'}, {})
                data=json.loads(payload)
                self.assertEqual(set(data['prior']),set(installer.targets(data)))
                self.assertEqual('producerWorkflow'in data['prior'],enabled)
                with mock.patch.object(installer.subprocess,'run',return_value=manager_result):
                    self.assertTrue(installer.preflight(data))
                    if enabled:
                        target=installer.targets(data)['producerWorkflow'];target.write_bytes(b'changed source grant')
                        with self.assertRaisesRegex(RuntimeError,'prior installed file/absence differs'):
                            installer.preflight(data)

    def test_source_medium_roundtrip_without_a_fake_package_descriptor(self):
        import tarfile,zipfile
        module=self.load('prepare_observer_iso')
        with tempfile.TemporaryDirectory()as temp:
            root=Path(temp);payload=root/'inputs.tar'
            with tarfile.open(payload,'x')as archive:
                item=tarfile.TarInfo('source/package.json');raw=b'{"private":true}'
                item.size=len(raw);archive.addfile(item,io.BytesIO(raw))
            definition={'kind':'UBUNTU_GUEST_SOURCE_INPUT_V1','compiled_or_packaged':False,
                'archive_bytes':payload.stat().st_size,'archive_sha256':hashlib.sha256(payload.read_bytes()).hexdigest(),
                'expanded_bytes':1024}
            candidate=root/'source-input.zip'
            with zipfile.ZipFile(candidate,'x')as archive:
                archive.write(payload,'ubuntu-source-inputs.tar')
                archive.writestr('source-input.json',json.dumps(definition))
            candidate.chmod(0o400)
            full9=('st_dev','st_ino','st_mode','st_uid','st_gid','st_nlink','st_size','st_mtime_ns','st_ctime_ns')
            ref={'path':str(candidate),'bytes':candidate.stat().st_size,
                 'sha256':hashlib.sha256(candidate.read_bytes()).hexdigest(),
                 'identity':{k:getattr(candidate.stat(),k)for k in full9}}
            programs={}
            for name in('ubuntu_guest_build.py','owned_command.py'):
                path=root/name;path.write_bytes((SOURCE/name).read_bytes());path.chmod(0o444)
                programs[name]={'path':str(path),'bytes':path.stat().st_size,
                    'sha256':hashlib.sha256(path.read_bytes()).hexdigest(),
                    'identity':{k:getattr(path.stat(),k)for k in full9}}
            descriptor={'kind':'UBUNTU_SOURCE_INPUT_ARTIFACT_V1','source_commit':'c'*40,
                        'producer_run_id':'12','producer_attempt':'2','input':definition}
            config={'kind':'ROOT_ADMITTED_UBUNTU_SOURCE_BUILD_V1','nonce':'a'*32,
                'candidate_source_commit':'c'*40,'source_input':{'descriptor':descriptor,'archive':ref},
                'source_input_cap_bytes':1048576,'prepared_directory':str(root/'prepared'),
                'guest_builder_source':programs['ubuntu_guest_build.py'],
                'owned_command_source':programs['owned_command.py'],'remaining_seconds':120}
            result=module.source_medium(config)
            actual=subprocess.run(['isoinfo','-R','-i',result['path'],'-x','/ubuntu-source-inputs.tar'],
                                  capture_output=True,check=True).stdout
            self.assertEqual(actual,payload.read_bytes())
            self.assertTrue(result['source_payload_readback'])
            self.assertFalse((root/'prepared/ubuntu-source-inputs.tar').exists())
            self.assertTrue(candidate.exists())
            self.assertFalse(result['VMOrGUIAcceptance'])
            subprocess.run(['bash','-n',str(root/'prepared/start.sh')],check=True)
            script=(root/'prepared/start.sh').read_text()
            self.assertIn('--admitted-source-build',script)
            self.assertNotIn('appimage-extract-and-run',script)

    def test_actual_source_ISO_readback_above_signed_2GiB_file_length(self):
        """Real ISO/reader/hash; sparse opaque input is not guest build acceptance."""
        import zipfile
        module=self.load('prepare_observer_iso')
        self.assertIsNotNone(shutil.which('bsdtar'))
        with tempfile.TemporaryDirectory()as temp:
            root=Path(temp);payload=root/'inputs.tar';size=2**31+65536
            with payload.open('xb')as output:
                output.truncate(size);output.seek(size-8);output.write(b'ENDINPUT')
            digest=hashlib.sha256()
            with payload.open('rb')as data:
                while block:=data.read(1048576):digest.update(block)
            definition={'kind':'UBUNTU_GUEST_SOURCE_INPUT_V1','compiled_or_packaged':False,
                'archive_bytes':size,'archive_sha256':digest.hexdigest(),'expanded_bytes':1024}
            candidate=root/'source-input.zip'
            with zipfile.ZipFile(candidate,'x',compression=zipfile.ZIP_DEFLATED,compresslevel=1)as archive:
                archive.write(payload,'ubuntu-source-inputs.tar')
                archive.writestr('source-input.json',json.dumps(definition))
            candidate.chmod(0o400)
            full9=('st_dev','st_ino','st_mode','st_uid','st_gid','st_nlink','st_size','st_mtime_ns','st_ctime_ns')
            def ref(path):
                raw=path.read_bytes()
                return {'path':str(path),'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest(),
                        'identity':{k:getattr(path.stat(),k)for k in full9}}
            programs={}
            for name in('ubuntu_guest_build.py','owned_command.py'):
                path=root/name;path.write_bytes((SOURCE/name).read_bytes());path.chmod(0o444);programs[name]=ref(path)
            descriptor={'kind':'UBUNTU_SOURCE_INPUT_ARTIFACT_V1','source_commit':'c'*40,
                        'producer_run_id':'12','producer_attempt':'2','input':definition}
            config={'kind':'ROOT_ADMITTED_UBUNTU_SOURCE_BUILD_V1','nonce':'a'*32,
                'candidate_source_commit':'c'*40,'source_input':{'descriptor':descriptor,'archive':ref(candidate)},
                'source_input_cap_bytes':67108864,'prepared_directory':str(root/'prepared'),
                'guest_builder_source':programs['ubuntu_guest_build.py'],
                'owned_command_source':programs['owned_command.py'],'remaining_seconds':120}
            result=module.source_medium(config)
            proof=json.loads((root/'prepared/source-ISO-readback.json').read_bytes())
            self.assertEqual((proof['numeric'],proof['bytes'],proof['sha256']),(0,size,digest.hexdigest()))
            self.assertTrue(result['source_payload_readback'])
            self.assertFalse((root/'prepared/ubuntu-source-inputs.tar').exists())
            self.assertTrue(candidate.exists());self.assertFalse(result['VMOrGUIAcceptance'])

