        ops.g={'nativeTools':{p:installer.pin(p)for p in ('/usr/bin/virt-xml-validate','/usr/bin/xmllint')},
               'issuedUnix':now-1,'startBeforeUnix':now+20,'preflightObservedUnix':now}
        ops.deadline=now+20
