    def test_physical_queue_capacity_backport_with_legacy_history_helpers(self):
        """Exact physical baseline + three functions; real private SQL/files only."""
        import ast
        import sqlite3
        import test_queue as current
        original=enrolled_subject_body('physical_test_queue.py').decode()
        sources=lambda text:{n.name:ast.get_source_segment(text,n)
            for n in ast.parse(text).body if isinstance(n,ast.FunctionDef)}
        before=sources(original)
        historical=Path(__file__).parent/'fixtures/omen-ci-legacy-capacity-functions.json'
        data=historical.read_bytes()
        self.assertEqual(hashlib.sha256(data).hexdigest(),'7483fed3ac3960e7f642e53565e288bfe9f56c29f5cc8f9ce899f605f4cc5b50')
        now=json.loads(data)['functions']
        candidate=original
        for name in ('enqueue','terminal_history_store','terminal_history_resolve'):
            candidate=candidate.replace(before[name],now[name])
        self.assertEqual(hashlib.sha256(candidate.encode()).hexdigest(),
            'd2d29bae09a0fdcea79511f84eb2b9f02d4ad57e72491f066e301d9ea6e4c86a')
        after=sources(candidate)
        self.assertEqual([k for k in before if before[k]!=after[k]],
            ['enqueue','terminal_history_store','terminal_history_resolve'])
        for name in ('history_directory','history_inventory','history_archive_index',
                     'history_publish','history_read_leaf'):
            self.assertEqual(before[name],after[name],'legacy helper must stay unchanged')
        legacy=types.ModuleType('actual_legacy_control_queue_capacity')
        legacy.__file__=str(SOURCE/'test_queue.py')
        exec(compile(candidate,legacy.__file__,'exec'),legacy.__dict__)
        with tempfile.TemporaryDirectory(prefix='opemos-legacy-capacity-')as tmp:
            state=Path(tmp)/'state'
            with contextlib.redirect_stdout(io.StringIO()):legacy.main(['--queue',str(state),'init'])
            root,db=legacy.connect(state)
            try:
                spec=lambda name:{'id':name,'cores':1,'memory':1024,'depends_on':[]}
                for i in range(257):
                    name='retained-'+str(i)
                    db.execute('INSERT INTO jobs VALUES(?,?,?,?,?,?,?,?)',
                        (name,legacy.canonical(spec(name)),'failed','[]',None,1.0,2.0,None))
                db.commit()
                retained=[tuple(r)for r in db.execute('SELECT * FROM jobs ORDER BY rowid')]
                legacy.enqueue(db,[spec('fresh-control')])
                self.assertEqual(db.execute('SELECT count(*) FROM jobs').fetchone()[0],258)
                self.assertEqual([tuple(r)for r in db.execute('SELECT * FROM jobs ORDER BY rowid')][:257],retained)
                with self.assertRaisesRegex(ValueError,'Duplicate job ID'):
                    legacy.enqueue(db,[spec('retained-0')])
                db.execute("UPDATE jobs SET state='failed',unit='fixture-unit',started=1,finished=2 WHERE id='fresh-control'");db.commit()
                epoch={'rows':[dict(r)for r in db.execute('SELECT * FROM jobs ORDER BY rowid')],
                       'pool':{'fixtureOnly':True},'bindings':[],
                       'config':[dict(r)for r in db.execute('SELECT * FROM config ORDER BY rowid')]}
                row=epoch['rows'][-1];invocation='a'*32
                db.execute('BEGIN IMMEDIATE')
                stored=legacy.terminal_history_store(db,epoch,row,invocation);db.commit()
                history_root,uid=legacy.history_root(db)
                self.assertEqual(stored['rowCount'],258)
                self.assertEqual(legacy.terminal_history_resolve(history_root,uid,stored,
                    row['id'],row['unit'],invocation),epoch)
                with self.assertRaisesRegex(ValueError,'Exact original terminal reference context'):
                    legacy.terminal_history_resolve(history_root,uid,
                        dict(stored,epochBytes=legacy.HISTORY_FILE_MAX+1),row['id'],row['unit'],invocation)
                duplicate=copy.deepcopy(epoch);duplicate['rows'].append(duplicate['rows'][0])
                db.execute('BEGIN IMMEDIATE')
                duplicate_ref=legacy.terminal_history_store(db,duplicate,row,invocation);db.commit()
                with self.assertRaisesRegex(ValueError,'Bounded unique complete history rows'):
                    legacy.terminal_history_resolve(history_root,uid,duplicate_ref,
                        row['id'],row['unit'],invocation)
                legacy.enqueue(db,[spec('pending-'+str(i))for i in range(256)])
                db.execute("UPDATE jobs SET state='unknown',finished=2 WHERE id='pending-0'");db.commit()
                with self.assertRaisesRegex(ValueError,'outstanding queue limit'):
                    legacy.enqueue(db,[spec('must-wait')])
            finally:db.close()

    def test_retained_terminal_history_does_not_consume_pending_capacity(self):
        import test_queue as queue
        import held_history_reader as reader
        import sqlite3
        # Real private SQL and ordinary enqueue; synthetic metadata ONLY.
        # No worker/command/grant/domain is run or claimed successful.
        with tempfile.TemporaryDirectory(prefix='opemos-capacity-') as tmp:
            state=Path(tmp)/'state'
            with contextlib.redirect_stdout(io.StringIO()):queue.main(['--queue',str(state),'init'])
            root,db=queue.connect(state)
            try:
                spec=lambda name:{'id':name,'cores':1,'memory':1024,'depends_on':[]}
                old=[]
                for i in range(256):
                    name='retained-'+str(i);old.append(name)
                    db.execute('INSERT INTO jobs VALUES(?,?,?,?,?,?,?,?)',(name,queue.canonical(spec(name)),'failed','[]',None,1.0,2.0,None))
                db.commit()
                queue.enqueue(db,[spec('fresh-one')])
                self.assertEqual(db.execute('SELECT count(*) FROM jobs').fetchone()[0],257)
                self.assertEqual([x[0]for x in db.execute('SELECT id FROM jobs ORDER BY rowid')][:256],old)
                db.setlimit(sqlite3.SQLITE_LIMIT_LENGTH,8*1024**2)
                values,stats=reader.read_private_history(db)
                self.assertEqual(len(values['rows']),257)
                self.assertEqual(values['rows'][-1]['id'],'fresh-one')
                with self.assertRaisesRegex(ValueError,'finite complete private history product'):
                    reader.read_private_history(db,maximum_bytes=128)
                queue.enqueue(db,[spec('pending-'+str(i))for i in range(255)])
                with self.assertRaisesRegex(ValueError,'outstanding queue limit'):
                    queue.enqueue(db,[spec('must-wait')])
                db.execute("UPDATE jobs SET state='failed',finished=2.0 WHERE id='fresh-one'");db.commit()
                with self.assertRaisesRegex(ValueError,'Duplicate job ID'):
                    queue.enqueue(db,[spec('retained-0')])
            finally:db.close()

